/* 기타검사 수정 */
UPDATE ETC_INSP
   SET INSP_NM      = #{inspection.inspNm}
     , INSP_RSLT_CN = #{inspection.inspRsltCn}
     , MEMO_CN      = #{inspection.memoCn}
     , MDFR_ID      = #{actorId}
     , MDFCN_DT     = NOW()
 WHERE ETC_INSP_SN = #{inspection.etcInspSn}
   AND DEL_YN = 'N'

/* 기타검사 삭제 */
UPDATE ETC_INSP
   SET DEL_YN   = 'Y'
     , MDFR_ID  = #{actorId}
     , MDFCN_DT = NOW()
 WHERE ETC_INSP_SN = #{etcInspSn}
   AND DEL_YN = 'N'
